import CategoryStockDashboard from './CategoryStockDashboard';

const Dashboard = () => {
    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold mb-8">Dashboard</h1>
            <CategoryStockDashboard />
        </div>
    );
};

export default Dashboard;
